import pandas as pd
import numpy as np

def analyze_permissions(user_permissions: pd.DataFrame) -> pd.DataFrame:
    if user_permissions.empty:
        return pd.DataFrame({'common_perms': [0], 'any_perms': [0]})
    common_val = np.bitwise_and.reduce(user_permissions['permissions'].values)
    any_val = np.bitwise_or.reduce(user_permissions['permissions'].values)
    return pd.DataFrame({'common_perms': [int(common_val)], 'any_perms': [int(any_val)]})
